import json,pathlib,subprocess,decimal
root=pathlib.Path.cwd();ev=root.parent.parent.parent/'out'/'F71c-evidence'
repo='https://github.com/CodexCoder21Organization/jvm-libp2p'
base=repo+'/blob/wip/F71c-20261024/investigation/F71c/'
def commit(short):return repo+'/commit/'+subprocess.check_output(['git','rev-parse',short],text=True).strip()
def rec(label):return json.loads((ev/(label+'.json')).read_text())
def ms(label):return int(decimal.Decimal(rec(label)['xml']['time'])*1000)
def link(label):return '[full record]('+base+label+'.xml)'
body=(ev/'body-before.md').read_text().strip()
footer='🤖 Generated with [Claude Code](https://claude.com/claude-code)'
assert body.endswith(footer)
body=body[:-len(footer)].rstrip()
old='The notification-site sweep also covers completed connection closes and stream writes. External completed closes no longer require accepted notification dispatch, while reentrant close ordering on the owning loop stays intact. Stream writes use the corrected converter. When a parent-write listener cannot enqueue its child completion on a full owning loop, it finishes that completion on the same loop; ordinary accepted deferral is preserved. Tests check success, exact original failure and payload release through both muxers.'
new='The notification-site sweep also covers completed connection closes, stream writes and capacity resets. Completed connection closes transfer their result directly outside an active public close-future callback; callback reentry and thread handoffs preserve earlier physical-close listener ordering. Stream writes and capacity-reset results use the corrected converter. Parent-write completion stays on the child loop, including when a custom muxer returns a promise whose listeners use another executor. Rejected delivery retains the completed result, while close and shutdown cancel stale delivery and release pending payloads. Tests check original success/failure/cancellation, exact rejection messages, later writes and payload release.'
assert old in body;body=body.replace(old,new)
body=body.replace('Registration audit: 23 original notification sites;', 'Round-2 registration audit (historical): 23 original notification sites;')
body=body.replace('GitHub Actions does not run tests for this fork: enterprise policy blocks its external actions, so the verification evidence is local. No workflow was rerun, requested or watched.', 'GitHub Actions has not provided executed-test verification for this fork; the verification evidence is local. Earlier startup failures were attributed to external-action policy. No workflow was rerun, requested or watched in this round.')
head=subprocess.check_output(['git','rev-parse','HEAD'],text=True).strip()
if (ev/'actions-final-head.json').exists():
 actions=json.loads((ev/'actions-final-head.json').read_text())['workflow_runs']
 links=', '.join('[startup-failure record]('+r['html_url']+')' for r in actions)
 if links:body+='\n\nCurrent final-head workflow records: '+links+'. Both completed before executing tests.'

section='''\n\n## Round 3\n\nThe owner requested the two fresh-context round-2 reviews' findings be closed test-first, with bounded Gradle commands, preserved first attempts, and no merge or publication. Those reviews examined `2a3b9e2f6e93e8c35e0897f3a6b8e1cc2d2adfc6`: [adversarial findings](ADVERSARIAL), [test-comprehensiveness findings](COVERAGE). This section supersedes the earlier close/write guard claims where the new probes found gaps.\n\n'''.replace('ADVERSARIAL',base+'R71adv2-findings.md').replace('COVERAGE',base+'R71tc2-findings.md')
rows=[
('Nested listener close', '37b0c7fe','6eb0c379','nested-red','nested-green','nested-reversal','A nested-listener close must complete after the event loop recovers'),
('Parent result on another executor','9a271e6d','1165d4e6','off-loop-red','termination-unflushed-deterministic-green','off-loop-reversal','A separate-executor parent result must settle its child write after queue recovery'),
('Early close handed to another thread','fdcc2831','d31c98ff','off-thread-red','off-thread-green','off-thread-reversal','A reentrant close must finish after previously registered physical-close listeners'),
('Additional sweep finding: capacity reset','832bd098','e2cc20fe','capacity-red','capacity-green','capacity-reversal','An already-closed stream must complete capacity reset after the event loop recovers')]
section+='| Finding | Test / fix | Red assertion and XML ms | Green XML ms | Reversal red XML ms |\n|---|---|---|---:|---:|\n'
for title,t,f,red,green,rev,message in rows:
 section+=f'| {title} | [test]({commit(t)}), [fix]({commit(f)}) | “{message}”; {ms(red)} {link(red)} | {ms(green)} {link(green)} | {ms(rev)} {link(rev)} |\n'
section+='\nThe close handoff red observed `[early listener, close operation, later listener]`; green requires `[early listener, later listener, close operation]`. Close notification scope is tracked explicitly across threads, rather than inferred from arbitrary promise nesting.\n\n'
section+=f'The parent-write test first had three result cases (all three red). [Retained delivery]({commit("d85e2afb")}) now runs only after actual dispatch rejection; it preserves the original result on the child loop. [Lifecycle guards]({commit("d1ededab")}) and [deterministic pending-parent setup]({commit("b4a6314a")}) cover explicit close, shutdown, and an application handler refusing close while an unflushed write remains. [Termination cleanup]({commit("1165d4e6")}) disposes both flushed and unflushed entries and avoids shutdown-hook submission after termination. The final six-case write guard is green. Reverting to the original mux code failed four of six cases; explicit close and ordinary pending shutdown already passed on that original code.\n\n'
section+=f'[Exact rejection-message assertions]({commit("33e551fc")}) check the original `null` message for both muxers. The final replacement-message mutation fails exactly those two cases: “The original queue rejection message must be retained ==> expected: <null> but was: <Review replacement lost the original queue rejection>”; {ms("rejection-message-final-mutation")} ms, {link("rejection-message-final-mutation")}.\n\n'
section+='The independent review passes also found two issues while developing this round. Their first attempts are retained, rather than replaced by later green runs:\n\n'
section+=f'- The first message-mutation run caught both intended assertions and an additional `RejectedExecutionException` while the existing stream test submitted its 2048 queue-fill tasks. The pre-armed periodic observer introduced ordinary queue work while the parent was pending. It was replaced with retained delivery only after actual rejection; the unchanged six-case stream test then passed. [First full failure record]({base}rejection-message-mutation-failures.txt).\n'
section+=f'- The first termination-cleanup red caught an unflushed child write left pending and `RejectedExecutionException: event executor terminated` during shutdown-hook removal. A first cleanup-fix attempt reached a normal successful parent completion before termination, failing “Terminated-loop writes must report the exact rejection”; that test had not forced the intended path. Holding the parent pending then produced the deterministic old-code red “Loop termination must settle accepted unflushed child writes” ({ms("termination-unflushed-deterministic-red")} ms), and the fixed code passed ({ms("termination-unflushed-deterministic-green")} ms). Every assertion and bound is retained. [Initial cleanup failure]({base}termination-unflushed-red-failures.txt), [intermediate failure]({base}termination-unflushed-green-failures.txt), [deterministic red]({base}termination-unflushed-deterministic-red.xml).\n\n'
section+=f'- The first 21-class register at `97e506d0` found the transport-gate assertion failing in `BufferedHalfCloseFramesTest`, and the pending-write assertion failing in `YamuxPrefixFrameFailureTest`. The new observer called `terminationFuture()` on caller-driven embedded loops, where that method throws `UnsupportedOperationException`; the application write therefore failed before its held transport completed. [The lifecycle capability guard]({commit("cf209084")}) limits shutdown/termination observers to owned autonomous loops. The unchanged tests then passed 14/14 and 1/1. A fresh register uses separate verified-* records at the corrected pushed head. [Buffering first failures]({base}final-BufferedHalfCloseFramesTest-failures.txt), [prefix first failure]({base}final-YamuxPrefixFrameFailureTest-failures.txt).\n\n'
section+='The dedicated test-comprehensiveness and code-review passes covered close callback handoff, unrelated nested notifications, all parent-result states, stale delivery after close, retained delivery cancellation, owner shutdown, blocked close, and unflushed termination. Findings and invariant updates are preserved in the [round-3 findings]('+base+'findings.md). No new external approval is claimed.\n\n'
section+='### Notification-site sweep\n\n24 logical sites: 20 existing ownership/guard boundaries, three corrected original sites, and one guarded new termination observer; four new guards in total. Pending Netty sources keep their documented normal listener-executor contract.\n\n'
sweep=(ev/'site-sweep.md').read_text();a=sweep.index('| Notification site');b=sweep.index('\n\nOBSERVED:',a);section+=sweep[a:b]+'\n\n'
section+=f'[Formatter commit]({commit("97e506d0")}): the configured repository formatter applied only to 14 Kotlin files and one Java file in the PR diff. The scoped check passed; actual FileCollection inputs and logs are preserved. Formatting changes imports, layout and braces, with no behavior change.\n\n'
section+='### Record correction\n\nThe specific final publish timeout in `GossipTwoHostTest.test message larger than mplex frame`, previously labelled `LOAD_SENSITIVE` in `F68c-final.md`, remains **unattributed** until matching develop evidence exists. The cited develop control failed at bind before publish; another develop record was a receive timeout, and the formatting profile came from a prior PR head. Those observations do not establish the cause of that final publish timeout. No evidence establishes that this PR caused or worsened it.\n\n'
results=json.loads((ev/'verified-register.json').read_text())
expected=(ev/'final-class-list.txt').read_text().splitlines()
section+=f'### Final-head first attempts\n\nPushed source head `{head}`. One class per bounded Gradle command; maximum observed concurrent Gradle commands across the round: **2**. Each command had a 25-minute maximum.\n\n'
section+='| Class | Pass / total | Fail / error / skip | XML ms |\n|---|---:|---:|---:|\n'
totals=[0,0,0,0]
for r in results:
 assert r['head']==head
 x=r.get('xml',{});n=int(x.get('tests',0));f=int(x.get('failures',0));e=int(x.get('errors',0));s=int(x.get('skipped',0));p=n-f-e-s
 totals=[totals[0]+n,totals[1]+f,totals[2]+e,totals[3]+s]
 section+=f'| {r["class"].rsplit(".",1)[1]} | {p}/{n} | {f}/{e}/{s} | {int(decimal.Decimal(x.get("time","0"))*1000)} |\n'
section+=f'\nRegister: {len(results)}/{len(expected)} classes; {totals[0]-sum(totals[1:])}/{totals[0]} pass, {totals[1]} failures, {totals[2]} errors, {totals[3]} skips. [All native XML, exact source controls and full failure records]({repo}/tree/wip/F71c-20261024/investigation/F71c). No failed unmodified test was rerun into green. No timeout or iteration count was changed, and no test/assertion was weakened, skipped or deleted.\n\n'
section+='All source and evidence are pushed. The PR remains open; this round did not merge, enqueue, publish, deploy or change a handoff. Owned Gradle daemons and compiler/test processes are stopped and a final process audit is preserved.\n'
newbody=body+section+'\n'+footer+'\n'
(ev/'body.json').write_text(json.dumps({'body':newbody},ensure_ascii=False,indent=2))
print('BODY_READY',len(newbody),'characters',len(results),'classes',totals)
